#if canImport(FoundationModels)
import Foundation
import FoundationModels

// MARK: - CV Metadata
// Metadata is not generated by AI, added after generation

public struct CVMetadata: Codable, Equatable, Sendable {
    public let generatedAt: Date
    public let generatedBy: String
    public let version: String

    public init(
        generatedAt: Date = Date(),
        generatedBy: String = "CVGeneratorAI",
        version: String = "1.0"
    ) {
        self.generatedAt = generatedAt
        self.generatedBy = generatedBy
        self.version = version
    }
}

// MARK: - CV Data

/// Core CV data model for AI generation
/// This model is designed to be flexible and AI-friendly
@Generable
public struct CVData: Codable, Equatable, Sendable {
    @Guide(description: "Personal and contact information")
    public let personalInfo: PersonalInfo

    @Guide(description: "Professional summary highlighting expertise and track record (3-4 sentences max, concise and impactful)")
    public let summary: String?

    @Guide(description: "Work experience in reverse chronological order (most recent first)")
    @Guide(.count(1...10))
    public let experience: [Experience]

    @Guide(description: "Educational background")
    @Guide(.count(0...5))
    public let education: [Education]

    @Guide(description: "Technical and professional skills grouped by category")
    public let skills: [Skill]

    @Guide(description: "Languages with CEFR proficiency levels")
    @Guide(.count(1...10))
    public let languages: [Language]

    @Guide(description: "Professional certifications")
    public let certifications: [Certification]

    @Guide(description: "Notable projects or contributions")
    public let projects: [Project]

    @Guide(description: "Personal interests and hobbies (optional)")
    public let interests: [String]

    public init(
        personalInfo: PersonalInfo,
        summary: String? = nil,
        experience: [Experience] = [],
        education: [Education] = [],
        skills: [Skill] = [],
        languages: [Language] = [],
        certifications: [Certification] = [],
        projects: [Project] = [],
        interests: [String] = []
    ) {
        self.personalInfo = personalInfo
        self.summary = summary
        self.experience = experience
        self.education = education
        self.skills = skills
        self.languages = languages
        self.certifications = certifications
        self.projects = projects
        self.interests = interests
    }
}
#endif
